* { box-sizing: border-box; }
body { margin: 0; color: #202a35; background: #f5f7fa; font: 16px/1.5 system-ui, sans-serif; }
main { max-width: 760px; margin: 4rem auto; padding: 0 1.25rem; }
h1 { margin: 0 0 1.5rem; font-size: 2rem; }
form { padding: 1.25rem; background: white; border: 1px solid #dce2e9; border-radius: 8px; }
label { display: block; margin-bottom: .4rem; font-weight: 600; }
.form-row { display: flex; gap: .65rem; }
input:not([type="checkbox"]) { min-width: 0; flex: 1; padding: .65rem; border: 1px solid #9aa8b7; border-radius: 4px; font: inherit; }
input[type="checkbox"] { width: 1.2rem; height: 1.2rem; }
select { margin-bottom: .75rem; padding: .5rem; font: inherit; }
button { padding: .6rem .9rem; border: 0; border-radius: 4px; color: white; background: #245cb4; font: inherit; cursor: pointer; }
button:hover { background: #19468e; }
